  longint cov_wen [5][8];
  longint cov_rdy0 [27], cov_rdy1 [27];
  longint cov_dly = 0;
  task automatic sample_cov();
    if (g_io_toIntPreg_0_wen) cov_wen[0][0]++;
    if (g_io_toIntPreg_1_wen) cov_wen[0][1]++;
    if (g_io_toIntPreg_2_wen) cov_wen[0][2]++;
    if (g_io_toIntPreg_3_wen) cov_wen[0][3]++;
    if (g_io_toIntPreg_4_wen) cov_wen[0][4]++;
    if (g_io_toIntPreg_5_wen) cov_wen[0][5]++;
    if (g_io_toIntPreg_6_wen) cov_wen[0][6]++;
    if (g_io_toIntPreg_7_wen) cov_wen[0][7]++;
    if (g_io_toFpPreg_0_wen) cov_wen[1][0]++;
    if (g_io_toFpPreg_1_wen) cov_wen[1][1]++;
    if (g_io_toFpPreg_2_wen) cov_wen[1][2]++;
    if (g_io_toFpPreg_3_wen) cov_wen[1][3]++;
    if (g_io_toFpPreg_4_wen) cov_wen[1][4]++;
    if (g_io_toFpPreg_5_wen) cov_wen[1][5]++;
    if (g_io_toVfPreg_0_wen) cov_wen[2][0]++;
    if (g_io_toVfPreg_1_wen) cov_wen[2][1]++;
    if (g_io_toVfPreg_2_wen) cov_wen[2][2]++;
    if (g_io_toVfPreg_3_wen) cov_wen[2][3]++;
    if (g_io_toVfPreg_4_wen) cov_wen[2][4]++;
    if (g_io_toVfPreg_5_wen) cov_wen[2][5]++;
    if (g_io_toV0Preg_0_wen) cov_wen[3][0]++;
    if (g_io_toV0Preg_1_wen) cov_wen[3][1]++;
    if (g_io_toV0Preg_2_wen) cov_wen[3][2]++;
    if (g_io_toV0Preg_3_wen) cov_wen[3][3]++;
    if (g_io_toV0Preg_4_wen) cov_wen[3][4]++;
    if (g_io_toV0Preg_5_wen) cov_wen[3][5]++;
    if (g_io_toVlPreg_0_wen) cov_wen[4][0]++;
    if (g_io_toVlPreg_1_wen) cov_wen[4][1]++;
    if (g_io_toVlPreg_2_wen) cov_wen[4][2]++;
    if (g_io_toVlPreg_3_wen) cov_wen[4][3]++;
    if (io_fromIntExu_3_1_valid) begin if (g_io_fromIntExu_3_1_ready) cov_rdy1[7]++; else cov_rdy0[7]++; end
    if (io_fromFpExu_0_1_valid) begin if (g_io_fromFpExu_0_1_ready) cov_rdy1[9]++; else cov_rdy0[9]++; end
    if (io_fromFpExu_1_1_valid) begin if (g_io_fromFpExu_1_1_ready) cov_rdy1[11]++; else cov_rdy0[11]++; end
    if (io_fromVfExu_2_0_valid) begin if (g_io_fromVfExu_2_0_ready) cov_rdy1[17]++; else cov_rdy0[17]++; end
    if (u_i.chk_valid[0][14] && u_i.chk_ready[0][14]) cov_dly++;   // 晚一拍那一路赢了
  endtask

  initial begin
    bit ok;
    void'($value$plusargs("ncycles=%d", NCYCLES));
    for (int unsigned cyc = 0; cyc < NCYCLES; cyc++) begin
      warm = (cyc < 4);
      drive();
      #1;
      if (cyc >= 5) compare();
      sample_cov();
      @(posedge clock); #1;
    end
    ok = 1;
    if (cov_wen[0][0] == 0) begin ok = 0; $display("COVER-MISS toIntPreg_0 never written"); end
    if (cov_wen[0][1] == 0) begin ok = 0; $display("COVER-MISS toIntPreg_1 never written"); end
    if (cov_wen[0][2] == 0) begin ok = 0; $display("COVER-MISS toIntPreg_2 never written"); end
    if (cov_wen[0][3] == 0) begin ok = 0; $display("COVER-MISS toIntPreg_3 never written"); end
