    if (cov_wen[1][2] == 0) begin ok = 0; $display("COVER-MISS toFpPreg_2 never written"); end
    if (cov_wen[1][3] == 0) begin ok = 0; $display("COVER-MISS toFpPreg_3 never written"); end
    if (cov_wen[1][4] == 0) begin ok = 0; $display("COVER-MISS toFpPreg_4 never written"); end
    if (cov_wen[1][5] == 0) begin ok = 0; $display("COVER-MISS toFpPreg_5 never written"); end
